SELECT d.DELIVERY_ID AS delivery_id,p.PIPELINE_CODE AS pipeline_code,COALESCE(r.RUN_LABEL,'') AS source_run_label,a.RUN_LABEL AS alert_run_label,c.CHANNEL_NAME AS channel,d.SOURCE_RUN_ID AS source_run_id,d.PIPELINE_RUN_ID AS alert_run_id,d.TRIGGER AS trigger,d.ATTEMPT_NUMBER AS attempt_number,CASE WHEN d.STATUS='ADMITTED' AND a.STATUS IN ('FAILED','CANCELLED') THEN 'FAILED' ELSE d.STATUS END AS status,d.STATUS_CODE AS status_code,d.ERROR_CLASS AS error_class,d.CREATED_AT AS created_at FROM AUD_ALERT_DELIVERIES d JOIN CFG_ALERT_CHANNELS c ON c.CHANNEL_ID=d.CHANNEL_ID LEFT JOIN AUD_PIPELINES_RUN_LOG r ON r.PIPELINE_RUN_ID=d.SOURCE_RUN_ID JOIN AUD_PIPELINES_RUN_LOG a ON a.PIPELINE_RUN_ID=d.PIPELINE_RUN_ID JOIN CFG_PIPELINES p ON p.PIPELINE_ID=a.PIPELINE_ID WHERE p.PROJECT_ID=:project_id AND c.PROJECT_ID=:project_id AND p.PIPELINE_CODE IN :pipeline_codes ORDER BY d.DELIVERY_ID DESC LIMIT 100
